#define LED_PIN 2

int load = 0;
float averageLoad = 0;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(115200);
}

void loop() {

  // Generate a test load between 400W and 800W
  load = random(400, 801);

  // For now, use a simple average around 500W
  averageLoad = 500;

  Serial.print("Load: ");
  Serial.print(load);
  Serial.print(" W | Average: ");
  Serial.print(averageLoad);
  Serial.println(" W");

  // High-load detection
  if (load > averageLoad) {

    // Blink LED
    digitalWrite(LED_PIN, HIGH);
    delay(300);
    digitalWrite(LED_PIN, LOW);
    delay(300);

  } else {

    // Normal load → LED OFF
    digitalWrite(LED_PIN, LOW);
    delay(1000);
  }
}
